            ['name' => 'Marisol  Mayorga Romero ', 'email' => 'mmayorga@actores.org.co', 'identificacion' => '1000687271', 'genero' => 'Mujer', 'tipo_socio' => 'Adherido', 'fecha_nacimiento' => '1999-04-17', 'direccion' => 'Cl 40a #13-24', 'telefono' => '3204610316', 'estado' => 'activo'],
            ['name' => 'Erick Nicolás Hernández Díaz', 'email' => 'nhernandez@actores.org.co', 'identificacion' => '1023019881', 'genero' => 'Hombre', 'tipo_socio' => 'Administrador', 'fecha_nacimiento' => '1997-03-16', 'direccion' => 'Dig 77 BIS sur No. 14P – 75 Barrio Miravalle', 'telefono' => '3229356936', 'estado' => 'activo'],

        ];

        foreach ($socios as $s) {
            // 1. SALTAMOS SI NO HAY EMAIL (Es la llave única principal)
            if (empty($s['email'])) {
                $this->command->warn("Saltando registro: Nombre " . ($s['name'] ?? 'Desconocido') . " no tiene email.");
                continue;
            }

            // 2. LIMPIEZA DE DATOS (Evitar fallos por campos requeridos vacíos)
            $idLimpia = isset($s['identificacion']) ? preg_replace('/[^0-9]/', '', $s['identificacion']) : null;

            // Si la identificación es nula o vacía, le asignamos algo temporal o la dejamos nula 
            // pero OJO: identificacion en tu tabla es UNIQUE. 
            // Si hay dos vacíos, fallará. Por eso validamos:
            if (empty($idLimpia)) {
                $idLimpia = null; // O podrías generar uno: 'PENDIENTE-' . uniqid();
            }

            try {
                DB::table('users')->updateOrInsert(
                    ['email' => trim($s['email'])], // Único criterio de búsqueda
                    [
                        'name'             => $s['name'] ?? 'Sin Nombre',
                        'identificacion'   => $idLimpia,
                        'genero'           => $s['genero'] ?? null,
                        'tipo_socio'       => $s['tipo_socio'] ?? 'Adherido',
                        'fecha_nacimiento' => $this->validarFecha($s['fecha_nacimiento'] ?? null),
                        'direccion'        => $s['direccion'] ?? null,
                        'telefono'         => $s['telefono'] ?? null,
                        'estado'           => $s['estado'] ?? 'Activo',
                        // Password: Solo se crea/actualiza si hay identificación
                        'password'         => $idLimpia ? Hash::make($idLimpia . '*2026') : Hash::make('Socio*2026'),
                        'created_at'       => now(),
                        'updated_at'       => now(),
                    ]
                );
            } catch (\Exception $e) {
                // Si algo falla (ej: identificación duplicada), lo atrapa y sigue con el siguiente
                $this->command->error("Error con el correo " . $s['email'] . ": " . $e->getMessage());
                Log::error("Error importando socio: " . $s['email'], ['error' => $e->getMessage()]);
            }
        }

        $this->command->info('Proceso de importación finalizado.');
    }

    /**
     * Valida que la fecha tenga un formato correcto para SQL
     */
    private function validarFecha($fecha)
    {
        if (!$fecha || $fecha == '0000-00-00') return null;
        try {
            return \Carbon\Carbon::parse($fecha)->format('Y-m-d');
        } catch (\Exception $e) {
            return null;
        }
    }
